Question: #include
 #include
 #include
 #include
 #include

 typedef struct Account {
 char first_name[50];
 int money;
 } Account;

 void transfer(){
 printf("The transfer function isn't complete yet.\n");
 }

 void withdraw(Account* acc, int value){
 if (value > acc->money || value 10000){
 printf("You are not allowed to withdraw that amount.\n");
 }
 if (value acc->money){
 return;
 }

 acc->money -= value;
 }

 void printMoney(Account acc){
 printf("Name: %s\nValue: $%d\n",acc.first_name,acc.money);
 return;
 }

 int main(int argc, char *argv[])
 {

 char username[100];

 printf("Enter your username:\n");
 scanf("%s",username);

 struct Account currentUser;

 currentUser.money = 0;
 strcpy(currentUser.first_name, username);

 int choice;
 printf("Enter your choice:\n");
 printf("1. transfer\n2. withdraw\n3. print money\n");
 scanf("%d",&choice);

 if (choice == 1){
 transfer();
 return 0;
 }
 else if (choice == 2){
 printf("Enter value to withdraw:\n");
 int val;
 scanf("%d",&val);
 withdraw(&currentUser, val);
 printMoney(currentUser);
 return 0;
 }
 else if (choice == 3){
 printMoney(currentUser);
 return 0;
 }


 return 0;
 }

 An attacker reasons he can exploit a program running the above source code. Full RELRO, stack canaries, NX, and PIE are all enabled. What is the easiest way to artificially inflate the amount of money a user has?
A. The attacker can input a negative value when withdrawing money, which will in turn add money to their account.
B. The attacker can input a very large number when attempting to withdraw money. This will cause an integer overflow, and cause the program to try and subtract a negative value, which will in turn add money to the user's account.
C. Use a long username to overwrite the money variable.
D. The attacker can input a very large input value when asked: "Enter your choice". A large value will cause an integer overflow which can then lead to arbitrary code execution or data corruption.
